 "title": "Bay Id"}, "code": {"maxLength": 80, "minLength": 1, "pattern": "^[A-Z0-9_+.-]+$", "title": "Code", "type": "string"}, "decision": {"default": "ACCEPT", "enum": ["ACCEPT", "DISMISS"], "title": "Decision", "type": "string"}, "leaf_id": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "title": "Leaf Id"}, "overhang_left_mm": {"anyOf": [{"minimum": 0.0, "type": "number"}, {"pattern": "^(?!^[-+.]*$)[+-]?0*\\d*\\.?\\d*$", "type": "string"}], "default": "0", "title": "Overhang Left Mm"}, "overhang_right_mm": {"anyOf": [{"minimum": 0.0, "type": "number"}, {"pattern": "^(?!^[-+.]*$)[+-]?0*\\d*\\.?\\d*$", "type": "string"}], "default": "0", "title": "Overhang Right Mm"}, "sides": {"anyOf": [{"items": {"enum": ["TOP", "RIGHT", "BOTTOM", "LEFT"], "type": "string"}, "maxItems": 4, "type": "array"}, {"type": "null"}], "default": null, "title": "Sides"}, "zone": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "title": "Zone"}}, "required": ["code"], "title": "ExtraSelection", "type": "object"}}, "additionalProperties": false, "properties": {"document_prices": {"default": "ITEMIZED", "enum": ["ITEMIZED", "GROUPED"], "title": "Document Prices", "type": "string"}, "position_defaults": {"items": {"$ref": "#/$defs/ExtraSelection"}, "maxItems": 30, "title": "Position Defaults", "type": "array"}, "schema_version": {"const": 1, "default": 1, "title": "Schema Version", "type": "integer"}, "services": {"items": {"$ref": "#/$defs/ExtraDefinition"}, "maxItems": 100, "title": "Services", "type": "array"}}, "title": "ExtraPolicy", "type": "object"}'::JSONB) THEN RETURN FALSE; END IF;
  RETURN NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p->'services') d WHERE d->>'kind'<>'SERVICE' OR NOT public.extra_definition_valid(d))
    AND (SELECT COUNT(DISTINCT d->>'code') FROM jsonb_array_elements(p->'services') d)=jsonb_array_length(p->'services')
    AND (SELECT COUNT(DISTINCT d->>'code') FROM jsonb_array_elements(p->'position_defaults') d)=jsonb_array_length(p->'position_defaults');
EXCEPTION WHEN OTHERS THEN RETURN FALSE;
END; $$;

ALTER TABLE public.profile_systems ADD COLUMN extra_authority JSONB
  CHECK (public.extra_authority_valid(extra_authority));
GRANT SELECT(extra_authority) ON public.profile_systems TO authenticated,catalog_backend,pricing_backend,documentary_backend;

CREATE TABLE public.organization_extra_settings (
  org_id UUID PRIMARY KEY REFERENCES public.tenancy_organizations(id) ON DELETE RESTRICT,
  policy JSONB NOT NULL CHECK(public.extra_policy_valid(policy)),
  revision INTEGER NOT NULL CHECK(revision>0),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
ALTER TABLE public.organization_extra_settings ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.organization_extra_settings FROM anon,authenticated;
GRANT SELECT,INSERT,UPDATE ON public.organization_extra_settings TO pricing_backend;
GRANT ALL ON public.organization_extra_settings TO service_role;
CREATE POLICY organization_extras_read ON public.organization_extra_settings FOR SELECT TO pricing_backend
  USING(org_id IN (SELECT private.current_user_org_ids()));
CREATE POLICY organization_extras_write ON public.organization_extra_settings FOR ALL TO pricing_backend
  USING(private.documentary_role(org_id,ARRAY['OWNER'])) WITH CHECK(private.documentary_role(org_id,ARRAY['OWNER']));

CREATE FUNCTION private.guard_extra_policy() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path=pg_catalog,public,private AS $$
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.org_id::TEXT||':extras',0));
  IF TG_OP='UPDATE' AND (NEW.org_id<>OLD.org_id OR NEW.revision<>OLD.revision+1) THEN
    RAISE EXCEPTION 'extra_policy_identity_or_revision_invalid' USING ERRCODE='23514';
  END IF;
  IF TG_OP='INSERT' AND NEW.revision<>1 AND NOT EXISTS(SELECT 1 FROM public.organization_extra_settings WHERE org_id=NEW.org_id) THEN
    RAISE EXCEPTION 'extra_policy_initial_revision_invalid' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END; $$;
REVOKE ALL ON FUNCTION private.guard_extra_policy() FROM PUBLIC;
CREATE TRIGGER extra_policy_identity BEFORE INSERT OR UPDATE ON public.organization_extra_settings
  FOR EACH ROW EXECUTE FUNCTION private.guard_extra_policy();

CREATE TABLE public.organization_extra_history (
  org_id UUID NOT NULL REFERENCES public.tenancy_organizations(id) ON DELETE RESTRICT,
  revision INTEGER NOT NULL,
  policy JSONB NOT NULL,
  actor_id UUID NOT NULL,
  reason TEXT NOT NULL CHECK(length(btrim(reason))>0),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY(org_id,revision)
);
ALTER TABLE public.organization_extra_history ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.organization_extra_history FROM anon,authenticated;
GRANT SELECT,INSERT ON public.organization_extra_history TO pricing_backend;
GRANT ALL ON public.organization_extra_history TO service_role;
CREATE POLICY organization_extras_history_read ON public.organization_extra_history FOR SELECT TO pricing_backend
  USING(private.documentary_role(org_id,ARRAY['OWNER']));
CREATE POLICY organization_extras_history_write ON public.organization_extra_history FOR INSERT TO pricing_backend
  WITH CHECK(private.documentary_role(org_id,ARRAY['OWNER']));
CREATE TRIGGER organization_extra_history_immutable BEFORE UPDATE OR DELETE ON public.organization_extra_history
  FOR EACH ROW EXECUTE FUNCTION private.reject_immutable_evidence();

CREATE TABLE public.project_extra_services (
  org_id UUID NOT NULL REFERENCES public.tenancy_organizations(id) ON DELETE RESTRICT,
  project_id UUID NOT NULL,
  revision_code TEXT NOT NULL CHECK(revision_code ~ '^REV-[A-Z]+$'),
  selections JSONB NOT NULL CHECK(jsonb_typeof(selections)='array' AND jsonb_array_length(selections)<=30),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY(org_id,project_id,revision_code),
  FOREIGN KEY(project_id,org_id) REFERENCES public.projects(id,org_id) ON DELETE RESTRICT
);
ALTER TABLE public.project_extra_services ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.project_extra_services FROM anon,authenticated;
GRANT SELECT,INSERT,UPDATE ON public.project_extra_services TO pricing_backend,documentary_backend;
GRANT ALL ON public.project_extra_services TO service_role;
CREATE POLICY project_extras_read ON public.project_extra_services FOR SELECT TO pricing_backend,documentary_backend
  USING(private.documentary_role(org_id,ARRAY['OWNER','ESTIMATOR','WORKSHOP_MANAGER']));
CREATE POLICY project_extras_write ON public.project_extra_services FOR ALL TO pricing_backend,documentary_backend
  USING(private.documentary_role(org_id,ARRAY['OWNER','ESTIMATOR']))
  WITH CHECK(private.documentary_role(org_id,ARRAY['OWNER','ESTIMATOR']));

CREATE FUNCTION private.guard_extra_services() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$
DECLARE p public.projects;
BEGIN
  IF TG_OP='UPDATE' AND (OLD.org_id,OLD.project_id,OLD.revision_code) IS DISTINCT FROM (NEW.org_id,NEW.project_id,NEW.revision_code) THEN
    RAISE EXCEPTION 'extra_service_identity_immutable' USING ERRCODE='23514';
  END IF;
  SELECT * INTO STRICT p FROM public.projects WHERE id=NEW.project_id AND org_id=NEW.org_id FOR UPDATE;
  IF p.status<>'DRAFT' OR p.current_revision<>NEW.revision_code
    OR EXISTS(SELECT 1 FROM public.project_versions WHERE project_id=p.id AND org_id=p.org_id AND revision_code=NEW.revision_code)
    OR private.project_has_applied_commercial_state(p.id) THEN
    RAISE EXCEPTION 'extra_services_revision_required' USING ERRCODE='23514';
  END IF;
  IF NOT public.hardware_schema_valid(NEW.selections,'{"$defs": {"ExtraSelection": {"additionalProperties": false, "properties": {"bay_id": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "title": "Bay Id"}, "code": {"maxLength": 80, "minLength": 1, "pattern": "^[A-Z0-9_+.-]+$", "title": "Code", "type": "string"}, "decision": {"default": "ACCEPT", "enum": ["ACCEPT", "DISMISS"], "title": "Decision", "type": "string"}, "leaf_id": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "title": "Leaf Id"}, "overhang_left_mm": {"anyOf": [{"minimum": 0.0, "type": "number"}, {"pattern": "^(?!^[-+.]*$)[+-]?0*\\d*\\.?\\d*$", "type": "string"}], "default": "0", "title": "Overhang Left Mm"}, "overhang_right_mm": {"anyOf": [{"minimum": 0.0, "type": "number"}, {"pattern": "^(?!^[-+.]*$)[+-]?0*\\d*\\.?\\d*$", "type": "string"}], "default": "0", "title": "Overhang Right Mm"}, "sides": {"anyOf": [{"items": {"enum": ["TOP", "RIGHT", "BOTTOM", "LEFT"], "type": "string"}, "maxItems": 4, "type": "array"}, {"type": "null"}], "default": null, "title": "Sides"}, "zone": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "title": "Zone"}}, "required": ["code"], "title": "ExtraSelection", "type": "object"}}, "items": {"$ref": "#/$defs/ExtraSelection"}, "type": "array"}'::JSONB,'{"$defs": {"ExtraSelection": {"additionalProperties": false, "properties": {"bay_id": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "title": "Bay Id"}, "code": {"maxLength": 80, "minLength": 1, "pattern": "^[A-Z0-9_+.-]+$", "title": "Code", "type": "string"}, "decision": {"default": "ACCEPT", "enum": ["ACCEPT", "DISMISS"], "title": "Decision", "type": "string"}, "leaf_id": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "title": "Leaf Id"}, "overhang_left_mm": {"anyOf": [{"minimum": 0.0, "type": "number"}, {"pattern": "^(?!^[-+.]*$)[+-]?0*\\d*\\.?\\d*$", "type": "string"}], "default": "0", "title": "Overhang Left Mm"}, "overhang_right_mm": {"anyOf": [{"minimum": 0.0, "type": "number"}, {"pattern": "^(?!^[-+.]*$)[+-]?0*\\d*\\.?\\d*$", "type": "string"}], "default": "0", "title": "Overhang Right Mm"}, "sides": {"anyOf": [{"items": {"enum": ["TOP", "RIGHT", "BOTTOM", "LEFT"], "type": "string"}, "maxItems": 4, "type": "array"}, {"type": "null"}], "default": null, "title": "Sides"}, "zone": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "title": "Zone"}}, "required": ["code"], "title": "ExtraSelection", "type": "object"}}, "items": {"$ref": "#/$defs/ExtraSelection"}, "type": "array"}'::JSONB) THEN
    RAISE EXCEPTION 'extra_service_selection_invalid' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END; $$;
REVOKE ALL ON FUNCTION private.guard_extra_services() FROM PUBLIC;
CREATE TRIGGER extra_service_editable BEFORE INSERT OR UPDATE ON public.project_extra_services
  FOR EACH ROW EXECUTE FUNCTION private.guard_extra_services();

COMMIT;
